SET "parse_code" = $gc$// "I just hit Genius on Spelling Bee." → 9: the rank's position on the ladder.
const RANKS = new Map([
  ["beginner", 1],
  ["good start", 2],
  ["moving up", 3],
  ["good", 4],
  ["solid", 5],
  ["nice", 6],
  ["great", 7],
  ["amazing", 8],
  ["genius", 9],
  ["queen bee", 10],
]);

function parse(raw) {
  const m = raw.match(/(?:hit|reached|got to|made it to)\s+([A-Za-z ]{2,20}?)\s+on/i);
  if (!m) throw new Error("no rank phrase");
  const rank = RANKS.get(m[1].trim().toLowerCase().replace(/\s+/g, " "));
  if (rank === undefined) throw new Error("unknown rank: " + m[1]);
  return rank;
}
