}

function parse(raw) {
  var lost = false;
  for (var i = 0; i < SPEC.rules.length; i++) {
    var value = evaluate(SPEC.rules[i], raw);
    if (typeof value === "number") return value;
    if (value === LOSS) lost = true;
  }
  if (lost) return null;
  throw new Error("no rule matched this share");
}
