INSERT INTO "game_code_revisions" ("game_id", "version", "parse_code", "format_code", "source", "note")
SELECT g."id", 1, g."parse_code", g."format_code", 'spec', 'Converted from the taught score/summary spec (migration 0043).'
FROM "games" g
WHERE g."code_version" = 1
  AND NOT EXISTS (SELECT 1 FROM "game_code_revisions" r WHERE r."game_id" = g."id");
